package io.github.ningpp.compat;

/**
 * Replacement for System.Text.Rune (generated by CSharpToJava converter).
 */
public final class Rune {
    private final int value;

    /** Mirrors Rune(int scalarValue). */
    public Rune(int scalarValue) {
        this.value = scalarValue;
    }

    /** Mirrors Rune.EncodeToUtf8(Span&lt;byte&gt;) — returns the number of bytes written. */
    public int encodeToUtf8(Span<Integer> destination) {
        byte[] bytes = new String(Character.toChars(value)).getBytes(java.nio.charset.StandardCharsets.UTF_8);
        int count = Math.min(bytes.length, destination.length());
        for (int i = 0; i < count; i++) {
            destination.set(i, bytes[i] & 0xFF);
        }
        return count;
    }

    public int getValue() {
        return value;
    }

    @Override
    public String toString() {
        return new String(Character.toChars(value));
    }
}
